package io.floci.aws.services.emrcontainers;

import com.fasterxml.jackson.databind.JsonNode;
import io.floci.aws.core.common.RequestConstraintCheck;

/**
 * Checks every EMR on EKS request, its body with the members its path and query string bind,
 * against the constraints generated by {@code tools/aws/regen_emr_containers_shapes.py}.
 */
final class EmrContainersRequestShapes {

    private static final RequestConstraintCheck CHECK = RequestConstraintCheck.load(
            "aws/emr-containers-request-shapes.json", "EMR on EKS request shapes",
            RequestConstraintCheck.standardMessages("ValidationException"));

    private EmrContainersRequestShapes() {
    }

    static void check(String operation, JsonNode request) {
        CHECK.check(operation, request);
    }
}
